<?php require '_init.php';$title='Catégories';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$n=trim($_POST['name']??'');if($n){$slug='cat-'.bin2hex(random_bytes(5));$s=$pdo->prepare("INSERT INTO categories(name,slug,description) VALUES(?,?,?)");$s->execute([$n,$slug,trim($_POST['description']??'')]);flash('Catégorie ajoutée.');}go('categories.php');}$cats=$pdo->query("SELECT c.*,COUNT(p.id) total FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name")->fetchAll();require '../includes/header.php';?><section class="banner"><div class="container"><h1>CATÉGORIES</h1></div></section><section class="container section"><div class="adminnav"><a href="dashboard.php">Dashboard</a><a href="products.php">Produits</a><a href="categories.php">Catégories</a><a href="orders.php">Commandes</a><a href="users.php">Utilisateurs</a></div><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Nom<input required name="name"></label><label>Description<textarea name="description"></textarea></label><button class="btn">Ajouter catégorie</button></form><div class="tablewrap"><table><tr><th>Nom</th><th>Description</th><th>Produits</th></tr><?php foreach($cats as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['description'])?></td><td><?=(int)$c['total']?></td></tr><?php endforeach?></table></div></section><?php require '../includes/footer.php';?>
